-- ============================================================
-- Unpublish off-topic articles (one-off data cleanup, 2026-10-18)
--
-- Commit 7edd290 (_shared/relevance.ts) stops new gadget/game/sports/
-- medical/lifestyle/politics/stock-tip stories from being generated.
-- This handles the ones already live.
--
-- How the list was built:
--   1. Pulled all 16613 published articles via the public REST API.
--   2. Ran offTopicReason(headline, summary + tags) from relevance.ts:
--      5810 hits.
--   3. Hand-reviewed every hit by headline (grouped by identical headline).
--      272 rows were false positives and are NOT in this list (funding,
--      layoffs, lawsuits, antitrust, earnings, AI/enterprise products,
--      security incidents, studio closures and union news).
--   4. Added 1 known miss by hand ("Decoding Grindr Lingo").
--
-- Effect: status 'published' -> 'rejected' for 5539 explicit ids.
-- The homepage and /startups/news read status = 'published' only.
-- 'rejected' matches the raw_signals vocabulary; articles.status is plain
-- text with no CHECK. Rows are not deleted. To undo, run the same UPDATE
-- with the statuses swapped.
--
-- Rows per reason:
--   gaming                    3014
--   consumer_device           1786
--   entertainment_lifestyle    419
--   general_politics           142
--   medical_research            73
--   sports                      85
--   stock_tips                  16
--   commodities                  3
--   manual_review                1
--   total                     5539
-- ============================================================

BEGIN;

UPDATE public.articles AS a
SET status = 'rejected'
